// ─── File: HaLoadBalancerDemo.java ───
// Redundant LB pair with a floating VIP + heartbeat failover, plus DNS zone failover.
import java.util.*;
import java.util.logging.*;

public class HaLoadBalancerDemo {
    private static final Logger log = Logger.getLogger("HA");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Zone az-1: an active-passive LB pair sharing one floating VIP.
        LoadBalancerNode active = new LoadBalancerNode("lb-az1-active", "az-1");
        LoadBalancerNode standby = new LoadBalancerNode("lb-az1-standby", "az-1");
        FloatingVip vip1 = new FloatingVip("10.0.0.100", active, standby);
        HeartbeatMonitor monitor = new HeartbeatMonitor(vip1);

        log.info("=== normal operation ===");
        vip1.serve("req-1");

        log.info("=== active LB node crashes → standby takes the VIP ===");
        active.crash();
        monitor.check();            // detects dead active, promotes standby
        vip1.serve("req-2");        // VIP unchanged; standby now serves

        // Zone az-2 has its own VIP; DNS fails over if az-1's whole pair is gone.
        LoadBalancerNode az2 = new LoadBalancerNode("lb-az2-active", "az-2");
        FloatingVip vip2 = new FloatingVip("10.1.0.100", az2, null);
        DnsFailover dns = new DnsFailover(List.of(vip1, vip2));

        log.info("=== entire az-1 pair becomes unreachable → DNS failover ===");
        standby.crash();            // now az-1 has NO healthy node
        monitor.check();
        String target = dns.resolve();     // DNS picks a healthy VIP
        log.info(() -> "DNS resolved api.nbi.example.com → " + target);
    }
}

// ─── node/LoadBalancerNode.java ───
class LoadBalancerNode {
    private final String name, zone;
    private boolean healthy = true;
    LoadBalancerNode(String name, String zone) { this.name = name; this.zone = zone; }
    String name() { return name; }
    String zone() { return zone; }
    boolean isHealthy() { return healthy; }
    void crash() { healthy = false; }
}

// ─── vip/FloatingVip.java (the shared virtual IP, assigned to the active node) ───
class FloatingVip {
    private static final Logger log = Logger.getLogger("HA");
    private final String address;
    private LoadBalancerNode active;
    private final LoadBalancerNode standby;
    FloatingVip(String address, LoadBalancerNode active, LoadBalancerNode standby) {
        this.address = address; this.active = active; this.standby = standby;
    }
    String address() { return address; }
    LoadBalancerNode active() { return active; }
    void promoteStandby() {
        if (standby != null && standby.isHealthy()) {
            log.warning(() -> "VIP " + address + " failover: " + active.name() + " → " + standby.name());
            active = standby;
        }
    }
    boolean isReachable() { return active != null && active.isHealthy(); }
    void serve(String reqId) {
        if (isReachable()) log.info(() -> "VIP " + address + " (" + active.name() + ") served " + reqId);
        else log.severe(() -> "VIP " + address + " UNREACHABLE for " + reqId);
    }
}

// ─── vip/HeartbeatMonitor.java (VRRP/keepalived-style detection + promotion) ───
class HeartbeatMonitor {
    private static final Logger log = Logger.getLogger("HA");
    private final FloatingVip vip;
    HeartbeatMonitor(FloatingVip vip) { this.vip = vip; }
    void check() {
        if (!vip.active().isHealthy()) {
            log.warning(() -> "Heartbeat lost from " + vip.active().name() + " — promoting standby");
            vip.promoteStandby();
        }
    }
}

// ─── dns/DnsFailover.java (zone/region-level failover across VIPs) ───
class DnsFailover {
    private static final Logger log = Logger.getLogger("HA");
    private final List<FloatingVip> vips;
    DnsFailover(List<FloatingVip> vips) { this.vips = vips; }
    // Return the first VIP that is reachable (DNS health-checked record set).
    String resolve() {
        for (FloatingVip v : vips) {
            if (v.isReachable()) return v.address();
            log.warning(() -> "DNS health check: VIP " + v.address() + " unreachable, trying next");
        }
        log.severe("All VIPs unreachable — total outage");
        return null;
    }
}

// ─── config/BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
